create or replace function observation_private.capture(filters jsonb) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=auth.uid(); sc text:=filters->>'scope'; tid uuid:=nullif(filters->>'teacher_id','')::uuid; dep text:=filters->>'department'; yr text:=filters->>'academic_year'; vids uuid[]; out_teachers jsonb; vs jsonb; rs jsonb; ds jsonb; start_date date:=nullif(filters->>'from','')::date; end_date date:=nullif(filters->>'to','')::date; known boolean; selected_ids uuid[]:=array(select value::uuid from jsonb_array_elements_text(coalesce(filters->'teacher_ids','[]')));
begin
 if uid is null then raise exception 'يلزم تسجيل الدخول' using errcode='42501'; end if;
 if sc not in ('teacher','department','school','selected') or sc is null then raise exception 'نطاق غير صالح'; end if;
 if sc='selected' and (cardinality(selected_ids)=0 or nullif(dep,'') is null or exists(select 1 from unnest(selected_ids) chosen(teacher_id) where not exists(select 1 from public.observation_teachers t where t.id=chosen.teacher_id and observation_private.teacher_access(t.id) and (t.department=dep or dep=any(t.departments))))) then raise exception 'المعلمات غير متاحات في القسم المحدد' using errcode='42501'; end if;
 if start_date>end_date then raise exception 'تاريخ البداية بعد النهاية'; end if;
 if sc='school' and not exists(select 1 from public.profiles p where p.id=uid and p.school_access='all' and p.role in ('principal','assistant_principal')) then raise exception 'تحليل المدرسة يتطلب صلاحية جميع الأقسام' using errcode='42501'; end if;
 if sc='teacher' and (tid is null or not observation_private.teacher_access(tid)) then raise exception 'المعلمة غير متاحة' using errcode='42501'; end if;
 if sc='department' and (nullif(dep,'') is null or not exists(select 1 from public.profiles p where p.id=uid and p.school_access='all' and p.role in ('principal','assistant_principal')) and not exists(select 1 from public.observation_access a join public.profiles p on p.id=a.user_id where a.user_id=uid and a.department=dep and p.role in ('assistant_principal','first_teacher','coordinator'))) then raise exception 'القسم غير متاح' using errcode='42501'; end if;
 select coalesce(array_agg(v.id),'{}'),coalesce(jsonb_agg(to_jsonb(v) order by v.visit_date,v.id),'[]') into vids,vs from public.classroom_visits v join public.observation_teachers t on t.id=v.teacher_id
 where v.status='final' and observation_private.teacher_access(t.id) and (sc<>'selected' or t.id=any(selected_ids)) and (sc<>'teacher' or t.id=tid) and (sc<>'department' or t.department=dep)
 and (start_date is null or v.visit_date>=start_date) and (end_date is null or v.visit_date<=end_date)
 and (nullif(yr,'') is null or v.academic_year=yr) and (nullif(filters->>'semester','') is null or v.semester=(filters->>'semester')::smallint)
 and (nullif(filters->>'visit_type','') is null or v.visit_type=filters->>'visit_type')
 and (nullif(filters->>'visit_id','') is null or v.id=(filters->>'visit_id')::uuid);
 select coalesce(jsonb_agg(to_jsonb(r) order by r.visit_id,r.criterion_id),'[]') into rs from public.classroom_visit_ratings r join public.classroom_visits v on v.id=r.visit_id where r.visit_id=any(vids) and observation_private.teacher_access(v.teacher_id,false,observation_private.domain_for(r.criterion_id));
 select coalesce(jsonb_agg(to_jsonb(d)),'[]') into ds from public.classroom_visit_details d join public.classroom_visits v on v.id=d.visit_id where d.visit_id=any(vids) and observation_private.teacher_access(v.teacher_id,false,0);
 select coalesce(jsonb_agg(to_jsonb(t) - 'user_id' order by t.full_name),'[]') into out_teachers from public.observation_teachers t where observation_private.teacher_access(t.id) and (sc<>'selected' or t.id=any(selected_ids)) and (sc<>'teacher' or t.id=tid) and (sc<>'department' or t.department=dep) and (t.id in (select teacher_id from public.classroom_visits where id=any(vids)) or t.active and t.academic_year=yr);
 known:=nullif(yr,'') is not null and exists(select 1 from public.observation_teachers t where t.active and t.academic_year=yr and observation_private.teacher_access(t.id) and (sc<>'selected' or t.id=any(selected_ids)) and (sc<>'teacher' or t.id=tid) and (sc<>'department' or t.department=dep));
 return jsonb_build_object('visits',vs,'ratings',rs,'details',ds,'teachers',out_teachers,'coverage_known',known,'coverage_teacher_ids',(select coalesce(jsonb_agg(t.id),'[]') from public.observation_teachers t where t.active and t.academic_year=yr and observation_private.teacher_access(t.id) and (sc<>'selected' or t.id=any(selected_ids)) and (sc<>'teacher' or t.id=tid) and (sc<>'department' or t.department=dep)));
end $$;
